import assert from 'node:assert/strict'
import {chromium} from 'playwright-core'
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--disable-gpu','--no-first-run']})
const page=await browser.newPage({viewport:{width:1660,height:1000}})
const failures=[];page.on('pageerror',e=>failures.push(e.message))
const read=()=>page.evaluate(()=>{const root=document.querySelector('.main-layout'),lib=root.querySelector('.asset-browser'),ins=root.querySelector('.clo-inspector'),view=root.querySelector('.workspaces');const box=e=>e.getBoundingClientRect().toJSON();return {root:root.dataset,library:box(lib),inspector:box(ins),viewer:box(view),libraryVisible:getComputedStyle(lib).visibility,inspectorVisible:getComputedStyle(ins).visibility}})
try{
 await page.goto('http://127.0.0.1:5971/?desktop=1&engine=clothcraft&testSession=universal-sidepanels-20261028',{waitUntil:'domcontentloaded'})
 await page.locator('.main-layout').waitFor()
 const initial=await read();assert(initial.viewer.width>600)
 const libGrip=page.getByRole('button',{name:'Drag Library panel'}).first()
 await libGrip.click({button:'right'})
 await page.getByRole('menuitem',{name:'Dock on right'}).click()
 const both=await read()
 assert.equal(both.root.exoLibrarySide,'right')
 console.log('GEOMETRY',JSON.stringify({viewer:both.viewer,library:both.library,inspector:both.inspector,side:both.root.exoLibrarySide}))
 assert(both.library.left>=both.viewer.right-5,'Library should not overlap viewer')
 assert(both.library.right<=both.inspector.left+5,'Library and inspector should not overlap')
 await libGrip.click({button:'right'})
 await page.getByRole('menuitem',{name:'Collapse panel'}).click()
 let collapsed=await read();assert.equal(collapsed.root.exoLibraryCollapsed,'true')
 await page.getByRole('button',{name:'Expand Library panel'}).click()
 collapsed=await read();assert.equal(collapsed.root.exoLibraryCollapsed,'false')
 await libGrip.click({button:'right'})
 await page.getByRole('menuitem',{name:'Dock on left'}).click()
 const restored=await read();assert.equal(restored.root.exoLibrarySide,'left')
 assert(restored.viewer.width>600)
 assert.equal(failures.length,0,failures.join('; '))
 console.log(JSON.stringify({ok:true,initialViewer:initial.viewer.width,rightLibrary:both.library,leftInspector:both.inspector,collapsed:collapsed.root.exoLibraryCollapsed,restored:restored.root.exoLibrarySide},null,2))
}finally{await browser.close()}
